 <script>
 document.addEventListener('DOMContentLoaded', function() {
  const container = document.querySelector('.cultivation-app-container');
  if (!container) return;

  // --- Navigation ---
  const navButtons = container.querySelectorAll('.nav-button');
  const panels = container.querySelectorAll('.panel');

  navButtons.forEach(button => {
   button.addEventListener('click', function() {
    const targetPanelClass = this.getAttribute('data-panel');
    if (!targetPanelClass) return;
    navButtons.forEach(btn => btn.classList.remove('active'));
    panels.forEach(panel => panel.classList.remove('active'));
    this.classList.add('active');
    const targetPanel = container.querySelector(`.panel.${targetPanelClass}`);
    if (targetPanel) { targetPanel.classList.add('active'); }
    else {
     console.error(`Panel not found: ${targetPanelClass}`);
     container.querySelector('.overview-panel')?.classList.add('active');
     container.querySelector('.nav-button[data-panel="overview-panel"]')?.classList.add('active');
    }
   });
  });

  // --- Data Processing ---
  const dataContainer = document.querySelector('.cultivation-data-container');

  function fetchDataAndProcess() {
   if (dataContainer && dataContainer.textContent.trim()) {
    try { processData(dataContainer.textContent.trim()); }
    catch (e) {
     console.error("Error processing data:", e);
     displayErrorInPanels(`处理数据时发生错误: ${e.message}`);
    }
   } else {
    console.warn("Data container is empty or not found.");
    displayErrorInPanels("未找到或系统数据为空");
   }
  }

  // --- Initial Data Load ---
  fetchDataAndProcess();

 }); // End DOMContentLoaded

 // --- Helper Functions (Utility Functions) ---
 function extractSectionContent(data, sectionName) {
  const regex = new RegExp(`\\[${sectionName}\\]([\\s\\S]*?)\\[\\/${sectionName}\\]`, 'i');
  const match = data.match(regex);
  return match ? match[1].trim() : '';
 }

 function parseProperties(item) {
  const properties = {};
  const pairs = item.match(/([^|()]+(\([^()]*\))*)+/g) || [];
  pairs.forEach(pair => {
   const firstColonIndex = pair.indexOf(':');
   if (firstColonIndex > 0) {
    const key = pair.substring(0, firstColonIndex).trim();
    let value = pair.substring(firstColonIndex + 1).trim();
    properties[key] = value;
   }
  });
  return properties;
 }

 function parseItemsInSection(sectionContent, stopMarker = null) {
  if (!sectionContent) return [];
  const lines = sectionContent.split('\n');
  const items = [];
  for (const line of lines) {
   const trimmedLine = line.trim();
   if (stopMarker && trimmedLine.includes(stopMarker)) break;
   if (trimmedLine.startsWith('[') && trimmedLine.includes(':') && trimmedLine.endsWith(']')) {
    const props = parseProperties(trimmedLine.slice(1, -1));
    if (Object.keys(props).length > 0) items.push(props);
   }
  }
  return items;
 }


 function extractPlainText(sectionContent) { // Extracts plain text lines
  if (!sectionContent) return '';
  return sectionContent.split('\n')
   .map(line => line.trim())
   .filter(line => line && !line.startsWith('[') && !line.startsWith('#') && !line.startsWith('-') && !line.includes(':'))
   .join('\n');
 }

 function extractListItems(sectionContent) { // Extracts list items
  if (!sectionContent) return [];
  return sectionContent.split('\n')
   .map(line => line.trim())
   .filter(line => line.startsWith('- ') || line.startsWith('* '))
   .map(line => line.substring(2));
 }

 function extractShopItems(sectionContent) { // Extracts shop items
  if (!sectionContent) return [];
  const items = [];
  const lines = sectionContent.split('\n').map(l => l.trim()).filter(l => l);
  const startIndex = lines.findIndex(l => /^\d+\./.test(l));
  if (startIndex === -1) return [];
  for (let i = startIndex; i < lines.length; i++) {
   const line = lines[i];
   const match = line.match(/^(\d+)\.\s*(.*?)\s*\((\d+)\s*点\):\s*(.*)/);
   if (match) items.push({ id: match[1], name: match[2].trim(), cost: parseInt(match[3], 10), description: match[4].trim() });
  }
  return items;
 }

//**V3 - Enhanced Task Parsing Logic**
function parseStructuredTasks(taskContent) {
   if (!taskContent) return [];
   const tasks = [];
   let currentTask = null;
   const taskBlocks = taskContent.split(/\n---\n/).map(block => block.trim()).filter(block => block);

   taskBlocks.forEach(block => {
       const lines = block.split('\n').map(l => l.trim()).filter(l => l);
       if (lines.length === 0) return;

       currentTask = null; // Reset for each block

       // Find the header line first
       const headerLineIndex = lines.findIndex(line => line.startsWith('[') && line.includes(':') && line.endsWith(']'));
       if (headerLineIndex === -1) return; // Skip blocks without a header

       const headerLine = lines[headerLineIndex];
       // **More Robust Header Regex:** Allows various prefixes before ":"
        // Allows names like "基础任务: X", "新增任务: Y", "新增任务链: Z(状态)"
       const headerMatch = headerLine.match(/^\[([^:]+):\s*(.*?)(?:\s*\((.*?)\))?\]$/);


       if (headerMatch) {
           currentTask = {
               name: headerMatch[2], // Task Name
               type: headerMatch[1], // Prefix like "基础任务", "新增任务" etc.
               status: headerMatch[3] || '进行中', // Status in parentheses, defaults to '进行中'
               details: [] // Array to store all other lines (objectives, rewards, etc.)
           };

           // Add all other lines as details
           for (let i = 0; i < lines.length; i++) {
               if (i === headerLineIndex) continue; // Skip the header line itself

               const detailLine = lines[i];
               // **Enhanced Detail Line Regex:** Captures keyword, content, and optional status
                // Matches lines like "[目标1: Desc (Status)]", "[子任务1: Desc]", "[环境: Desc]"
               const detailMatch = detailLine.match(/^\[([^:]+):\s*(.*?)(?:\s*\((.*?)\))?\]$/);

               if (detailMatch) {
                   currentTask.details.push({
                       keyword: detailMatch[1].trim(), // e.g., "目标1", "奖励", "子任务1", "当前环境安全评估"
                       text: detailMatch[2].trim(),    // Content after the colon
                       status: detailMatch[3] ? detailMatch[3].trim() : '' // Status in parentheses, if exists
                   });
               } else {
                   // Handle lines that don't fit the "[keyword: content (status)]" format if needed
                   // console.warn("Unparsed task detail line:", detailLine);
                    // Or push as a simple text detail:
                    // currentTask.details.push({ keyword: '描述', text: detailLine, status: '' });
               }
           }
           tasks.push(currentTask);
       }
   });

