 margin-top: 12px; padding-top: 10px; border-top: 1px dotted var(--border-secondary); display: grid;
 grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 8px 18px; font-size: 0.9em; color: var(--text-primary); line-height: 1.7;
 }
 .status-panel .player-basic-info strong { color: var(--highlight-progress); }
 .status-panel .player-basic-info .lingneng strong { color: var(--highlight-primary); }
 .status-panel .player-basic-info .lingneng span { color: var(--highlight-secondary); font-weight: bold; }
 .status-panel .player-detailed-info strong { color: var(--text-secondary); }
 .status-panel .player-detailed-info i { margin-right: 5px; width: 1.1em; text-align: center; }

 .status-panel .daopath-details-grid { grid-template-columns: 1fr; gap: 10px; }
