 .status-panel .daopath-item:last-child { border-bottom: none; }
 .status-panel .daopath-info { display: flex; justify-content: space-between; align-items: center; }
 .status-panel .daopath-info strong { font-weight: 500; display: inline-block; min-width: 40px; }
 .status-panel .daopath-info span { font-weight: bold; margin-left: 10px; }
 .status-panel .dao-description {
 font-size: 0.85em; color: var(--text-secondary); margin-top: 5px; padding-left: 10px; line-height: 1.5; border-left: 2px solid var(--border-primary);
 }

 /* Dao Path Colors */
 .status-panel .dao-shufu strong { color: var(--dao-shufu-text); } .status-panel .dao-shufu span { color: var(--dao-shufu-value); }
 .status-panel .dao-zhipei strong { color: var(--dao-zhipei-text); } .status-panel .dao-zhipei span { color: var(--dao-zhipei-value); }
 .status-panel .dao-meihuo strong { color: var(--dao-meihuo-text); } .status-panel .dao-meihuo span { color: var(--dao-meihuo-value); }
 .status-panel .dao-gaizao strong { color: var(--dao-gaizao-text); } .status-panel .dao-gaizao span { color: var(--dao-gaizao-value); }
 .status-panel .dao-baolu strong { color: var(--dao-baolu-text); } .status-panel .dao-baolu span { color: var(--dao-baolu-value); }

 /* --- Utility Styles --- */
 .no-data {
 display: flex; flex-direction: column; align-items: center; justify-content: center;
 min-height: 100px; color: var(--text-secondary); text-align: center; padding: 15px; font-size: 0.9em;
 }
 .no-data i { font-size: 2rem; margin-bottom: 10px; color: var(--border-primary); }

 </style>
</head>
<body>
 <!-- Container for raw data, hidden from view -->
 <div class="cultivation-data-container">$1</div>

 <div class="cultivation-app-container">
  <!-- Title Bar -->
  <div class="app-title-bar">
   <div class="app-title">
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M12.378 1.602a.75.75 0 00-.756 0L3.366 6.166A.75.75 0 003 6.821v10.358c0 .311.18.588.455.711l8.256 3.753a.75.75 0 00.578 0l8.256-3.753a.75.75 0 00.455-.711V6.821a.75.75 0 00-.366-.655L12.378 1.602zm-1.64 4.625a.75.75 0 01.75-.032l6.938 3.153a.75.75 0 010 1.304l-6.938 3.154a.75.75 0 11-.718-1.272l5.24-2.381-5.24-2.381a.75.75 0 01-.032-.741z"></path></svg>
    <span>色色修仙系统</span>
   </div>
   <div class="app-controls"></div> <!-- Keep for structure -->
  </div>

  <!-- Content Area for Panels -->
  <div class="app-content">
   <div class="panel overview-panel active">加载总览数据中...</div>
   <div class="panel character-panel">加载人物数据中...</div>
   <div class="panel inventory-panel">加载背包数据中...</div>
   <div class="panel status-panel">加载状态数据中...</div>
  </div>

  <!-- Navigation Bar -->
  <div class="app-navbar">
   <div class="nav-button active" data-panel="overview-panel"> <i class="fas fa-tachometer-alt"></i> <span>总览</span> </div>
   <div class="nav-button" data-panel="character-panel"> <i class="fas fa-users"></i> <span>人物</span> </div>
   <div class="nav-button" data-panel="inventory-panel"> <i class="fas fa-box-open"></i> <span>背包</span> </div>
   <div class="nav-button" data-panel="status-panel"> <i class="fas fa-heartbeat"></i> <span>状态</span> </div>
  </div>
 </div>

 <script>
 document.addEventListener('DOMContentLoaded', function() {
  const container = document.querySelector('.cultivation-app-container');
  if (!container) return;

  // --- Navigation ---
  const navButtons = container.querySelectorAll('.nav-button');
  const panels = container.querySelectorAll('.panel');

  navButtons.forEach(button => {
   button.addEventListener('click', function() {
    const targetPanelClass = this.getAttribute('data-panel');
    if (!targetPanelClass) return;
    navButtons.forEach(btn => btn.classList.remove('active'));
    panels.forEach(panel => panel.classList.remove('active'));
    this.classList.add('active');
    const targetPanel = container.querySelector(`.panel.${targetPanelClass}`);
    if (targetPanel) { targetPanel.classList.add('active'); }
    else {
     console.error(`Panel not found: ${targetPanelClass}`);
     container.querySelector('.overview-panel')?.classList.add('active');
     container.querySelector('.nav-button[data-panel="overview-panel"]')?.classList.add('active');
    }
   });
  });

  // --- Data Processing ---
  const dataContainer = document.querySelector('.cultivation-data-container');

  function fetchDataAndProcess() {
   if (dataContainer && dataContainer.textContent.trim()) {
    try { processData(dataContainer.textContent.trim()); }
    catch (e) {
     console.error("Error processing data:", e);
     displayErrorInPanels(`处理数据时发生错误: ${e.message}`);
    }
   } else {
    console.warn("Data container is empty or not found.");
    displayErrorInPanels("未找到或系统数据为空");
   }
  }

  // --- Initial Data Load ---
  fetchDataAndProcess();

 }); // End DOMContentLoaded

 // --- Helper Functions (Utility Functions) ---
 function extractSectionContent(data, sectionName) {
  const regex = new RegExp(`\\[${sectionName}\\]([\\s\\S]*?)\\[\\/${sectionName}\\]`, 'i');
  const match = data.match(regex);
  return match ? match[1].trim() : '';
 }

 function parseProperties(item) {
  const properties = {};
  const pairs = item.match(/([^|()]+(\([^()]*\))*)+/g) || [];
  pairs.forEach(pair => {
   const firstColonIndex = pair.indexOf(':');
   if (firstColonIndex > 0) {
    const key = pair.substring(0, firstColonIndex).trim();
    let value = pair.substring(firstColonIndex + 1).trim();
    properties[key] = value;
   }
  });
  return properties;
 }

 function parseItemsInSection(sectionContent, stopMarker = null) {
  if (!sectionContent) return [];
  const lines = sectionContent.split('\n');
  const items = [];
  for (const line of lines) {
   const trimmedLine = line.trim();
   if (stopMarker && trimmedLine.includes(stopMarker)) break;
   if (trimmedLine.startsWith('[') && trimmedLine.includes(':') && trimmedLine.endsWith(']')) {
    const props = parseProperties(trimmedLine.slice(1, -1));
    if (Object.keys(props).length > 0) items.push(props);
   }
  }
  return items;
 }


 function extractPlainText(sectionContent) { // Extracts plain text lines
  if (!sectionContent) return '';
  return sectionContent.split('\n')
   .map(line => line.trim())
   .filter(line => line && !line.startsWith('[') && !line.startsWith('#') && !line.startsWith('-') && !line.includes(':'))
   .join('\n');
 }

 function extractListItems(sectionContent) { // Extracts list items
  if (!sectionContent) return [];
  return sectionContent.split('\n')
   .map(line => line.trim())
   .filter(line => line.startsWith('- ') || line.startsWith('* '))
   .map(line => line.substring(2));
 }

 function extractShopItems(sectionContent) { // Extracts shop items
  if (!sectionContent) return [];
  const items = [];
  const lines = sectionContent.split('\n').map(l => l.trim()).filter(l => l);
  const startIndex = lines.findIndex(l => /^\d+\./.test(l));
  if (startIndex === -1) return [];
  for (let i = startIndex; i < lines.length; i++) {
   const line = lines[i];
   const match = line.match(/^(\d+)\.\s*(.*?)\s*\((\d+)\s*点\):\s*(.*)/);
   if (match) items.push({ id: match[1], name: match[2].trim(), cost: parseInt(match[3], 10), description: match[4].trim() });
  }
  return items;
 }

//**V3 - Enhanced Task Parsing Logic**
function parseStructuredTasks(taskContent) {
   if (!taskContent) return [];
   const tasks = [];
   let currentTask = null;
   const taskBlocks = taskContent.split(/\n---\n/).map(block => block.trim()).filter(block => block);

   taskBlocks.forEach(block => {
       const lines = block.split('\n').map(l => l.trim()).filter(l => l);
       if (lines.length === 0) return;

       currentTask = null; // Reset for each block

       // Find the header line first
       const headerLineIndex = lines.findIndex(line => line.startsWith('[') && line.includes(':') && line.endsWith(']'));
       if (headerLineIndex === -1) return; // Skip blocks without a header

       const headerLine = lines[headerLineIndex];
       // **More Robust Header Regex:** Allows various prefixes before ":"
        // Allows names like "基础任务: X", "新增任务: Y", "新增任务链: Z(状态)"
       const headerMatch = headerLine.match(/^\[([^:]+):\s*(.*?)(?:\s*\((.*?)\))?\]$/);


       if (headerMatch) {
           currentTask = {
               name: headerMatch[2], // Task Name
               type: headerMatch[1], // Prefix like "基础任务", "新增任务" etc.
               status: headerMatch[3] || '进行中', // Status in parentheses, defaults to '进行中'
               details: [] // Array to store all other lines (objectives, rewards, etc.)
           };

           // Add all other lines as details
           for (let i = 0; i < lines.length; i++) {
               if (i === headerLineIndex) continue; // Skip the header line itself

               const detailLine = lines[i];
               // **Enhanced Detail Line Regex:** Captures keyword, content, and optional status
                // Matches lines like "[目标1: Desc (Status)]", "[子任务1: Desc]", "[环境: Desc]"
               const detailMatch = detailLine.match(/^\[([^:]+):\s*(.*?)(?:\s*\((.*?)\))?\]$/);

               if (detailMatch) {
                   currentTask.details.push({
                       keyword: detailMatch[1].trim(), // e.g., "目标1", "奖励", "子任务1", "当前环境安全评估"
                       text: detailMatch[2].trim(),    // Content after the colon
                       status: detailMatch[3] ? detailMatch[3].trim() : '' // Status in parentheses, if exists
                   });
               } else {
                   // Handle lines that don't fit the "[keyword: content (status)]" format if needed
                   // console.warn("Unparsed task detail line:", detailLine);
                    // Or push as a simple text detail:
                    // currentTask.details.push({ keyword: '描述', text: detailLine, status: '' });
               }
           }
           tasks.push(currentTask);
       }
   });

   // console.log("Parsed Tasks V3:", tasks); // Debug log
   return tasks;
}


 function displayError(element, message) { // Displays error message
  if (!element) return;
  element.innerHTML = `<div class="no-data"><i class="fas fa-exclamation-triangle"></i><p>${message}</p></div>`;
 }

 function displayErrorInPanels(message) { // Displays error in all panels
  const container = document.querySelector('.cultivation-app-container');
  if (!container) return;
  container.querySelectorAll('.panel').forEach(panel => { displayError(panel, message); });
 }

 // --- Main Data Processing Logic ---
 function processData(data) {
  const timeData = extractSectionContent(data, 'time_info');
  const playerDataRaw = extractSectionContent(data, 'player_info');
  const daoPathData = extractSectionContent(data, 'dao_paths');
  const characterData = extractSectionContent(data, 'characters_info');
  const inventoryData = extractSectionContent(data, 'inventory_info');
  const tasksData = extractSectionContent(data, 'tasks_info');
  const shopData = extractSectionContent(data, 'shop_info');

  handleOverviewData(timeData, tasksData, shopData); // Uses V3 task parsing
  handleCharacterData(characterData);
  handleInventoryData(inventoryData);
  handleStatusData(playerDataRaw, daoPathData);
 }

 // --- Panel Specific Handlers ---

 //**MODIFIED handleOverviewData to work with V3 task structure**
function handleOverviewData(timeRaw, tasksRaw, shopRaw) {
   const panel = document.querySelector('.overview-panel');
   if (!panel) return;

   const timeInfo = parseItemsInSection(timeRaw)[0] || {};
   const tasks = parseStructuredTasks(tasksRaw); // Uses V3 parser
   const shopPointsMatch = shopRaw.match(/可用点数:\s*(\d+)\s*情欲灵能/);
   const shopPoints = shopPointsMatch ? shopPointsMatch[1] : '0';
   const shopItems = extractShopItems(shopRaw);

   let html = `
   <div class="top-status-bar">
    <span><i class="fas fa-clock"></i> <strong>时刻:</strong> ${timeInfo['时刻'] || '未知'}</span>
    <span><i class="far fa-calendar-alt"></i> <strong>纪日:</strong> ${timeInfo['纪日'] || '未知'}</span>
    <span><i class="fas fa-globe-asia"></i> <strong>界域:</strong> ${timeInfo['界域'] || '凡界'}</span>
   </div>
   <div class="info-section">
    <details open>
     <summary><i class="fas fa-tasks"></i> 系统天命 / 任务</summary>
     <div class="task-section content-section">
      ${tasks.length > 0 ? tasks.map(task => {
       const isTaskCompleted = task.status === '已完成';
       let taskHTML = `<div class="task-item ${isTaskCompleted ? 'completed' : ''}">`;
       taskHTML += `<span class="task-header ${isTaskCompleted ? 'completed' : ''}">【${task.type}】${task.name} ${task.status && task.status !== '进行中' ? '(' + task.status + ')' : ''}</span>`;

       // Iterate through task details
       task.details.forEach(detail => {
           let detailClass = 'task-details-line'; // Default class
           let statusText = detail.status ? `(${detail.status})` : '';
            let isComplete = false; // Use for styling completed objectives etc.

           // Apply specific classes and check for completion based on keyword
           if (detail.keyword.startsWith('目标')) {
                detailClass += ' task-objective';
                 isComplete = /\d\/\d/.test(detail.status) ? (detail.status.split('/')[0] === detail.status.split('/')[1]) : (detail.status.includes('已达成') || detail.status.includes('1/1') || isTaskCompleted);
                 if (isComplete) detailClass += ' completed';
            } else if (detail.keyword === '奖励') {
                detailClass += ' task-reward';
                 isComplete = detail.status.includes('已领取') || isTaskCompleted;
                 if (isComplete) detailClass += ' claimed';
                 if(isComplete && !statusText) statusText = '(已领取)'; // Add claimed text if status missing but task done
            } else if (detail.keyword.startsWith('子任务')) {
                detailClass += ' task-subtask';
                // Potentially add completion logic for subtasks if needed
            } else if (detail.keyword.includes('环境')) {
               detailClass += ' task-environment';
            }
           // Add more keyword checks here if needed (e.g., '条件', '提示')

           taskHTML += `<span class="${detailClass}">${detail.keyword}: ${detail.text} ${statusText}</span>`;
       });

       taskHTML += `</div>`;
       return taskHTML;
      }).join('') : '<div class="no-data"><p>暂无活动任务</p></div>'}
     </div>
    </details>
 <details>
     <summary><i class="fas fa-store"></i> 虚空易市 / 商店</summary>
     <div class="shop-section">
         <div class="shop-points">可用点数: ${shopPoints} 情欲灵能</div>
         ${shopItems.length > 0 ? shopItems.map(item => `
             <div class="item">
                 <div class="item-name">${item.id}. ${item.name}</div>
                 <div class="item-desc">${item.description}</div>
                 <div class="item-cost">价格: ${item.cost} 点</div>
             </div>
         `).join('') : '<p>今日无货</p>'}
     </div>
     </details>
   </div>`;
   panel.innerHTML = html;
}


 function handleCharacterData(data) { // No changes needed
  const panel = document.querySelector('.character-panel'); if (!panel) return;
  const presentCharsRaw = data.split('[other_characters_summary]')[0];
  const summaryRaw = extractSectionContent(data, 'other_characters_summary');
  const presentCharacters = parseItemsInSection(presentCharsRaw.replace(/\[player_info\]/g, '').trim(), '#');

  if (presentCharacters.length === 0 && !summaryRaw) { displayError(panel, "未发现人物因果信息"); return; }
  let html = '<div class="character-cards-container">';
  if (presentCharacters.length > 0) {
   html += '<h5 class="section-header">当前交互</h5>';
   presentCharacters.forEach(char => {
    const name = char['姓名'] || '未知', age = char['年龄'] || '?', cultivation = char['修为'] || '凡人', relation = char['关系'] || '未知',
     status = char['状态'] || '平常', thoughts = char['想法'] || '无', vagina = char['阴道'] || '未探', anus = char['后庭'] || '未探',
     breasts = char['乳房'] || '未探', penis = char['阳具'];
    html += `<div class="character-card"><div class="card-header"><span class="char-name">${name} <span>(${cultivation})</span></span><span class="char-relation">关系: ${relation}</span></div><p class="char-status"><strong>状态:</strong> ${status}</p>${thoughts !== '无' ? `<p class="char-thoughts"><i>想法: ${thoughts}</i></p>` : ''}<details><summary>详细 (年龄: ${age})...</summary><div class="char-details-content"><p>阴道: ${vagina}</p><p>后庭: ${anus}</p><p>乳房: ${breasts}</p>${penis ? `<p>阳具: ${penis}</p>` : ''}</div></details></div>`;
   });
  } else { html += '<h5 class="section-header">当前交互</h5>'; html += '<div class="no-data"><i class="fas fa-user-slash"></i><p>当前无交互对象</p></div>'; }
  html += '</div>';
  if (summaryRaw) { html += `<div class="other-characters-section"><details><summary><i class="fas fa-users-slash"></i> 其他人物概览</summary><div class="other-characters-content">${summaryRaw.replace(/\|/g, '<br>')}</div></details></div>`; }
  panel.innerHTML = html;
 }

 function handleInventoryData(data) { // No changes needed
  const panel = document.querySelector('.inventory-panel'); if (!panel) return;
  const listItems = extractListItems(data); const otherText = extractPlainText(data);
  if (listItems.length === 0 && !otherText) { displayError(panel, "乾坤袋空空如也"); return; }
  let html = `<h5 class="section-header"><i class="fas fa-box-open"></i> 乾坤袋 / 背包</h5> <div class="inventory-content">`;
  if(otherText) html += `<p>${otherText.replace(/\n/g, '<br>')}</p>`;
  if(listItems.length > 0) html += `<ul>${listItems.map(item => `<li>${item}</li>`).join('')}</ul>`;
  html += `</div>`; panel.innerHTML = html;
 }

 function handleStatusData(playerRaw, daoPathRaw) { // V2 player info parsing already correct
  const panel = document.querySelector('.status-panel'); if (!panel) return;
  const playerBlocks = playerRaw.split('\n').map(l => l.trim()).filter(l => l.startsWith('[player_info]'));
  const playerBasic = playerBlocks.length > 0 ? parseProperties(playerBlocks[0].slice('[player_info]'.length, -1)) : {};
  const playerDetailed = playerBlocks.length > 1 ? parseProperties(playerBlocks[1].slice('[player_info]'.length, -1)) : {};
  const daoPaths = parseItemsInSection(daoPathRaw);
  const daoDescriptions = {
       '束缚': '通过物理或法术手段限制目标的行动自由...', // Simplified
       '支配': '以言语、姿态、气场或权力关系主导情欲互动的走向...',
       '魅惑': '运用自身的魅力、技巧主动挑逗、引诱目标...',
       '改造': '通过外力暂时或永久性地改变目标的身体形态...',
       '暴露': '在有被窥视风险或公开环境下进行裸露或性事...'
   }; // Keep descriptions very short or integrated differently if space is an issue.

  let html = `<details open><summary><i class="fas fa-user-circle"></i> 玩家状态: ${playerBasic['姓名'] || '未知'} (${playerBasic['修为'] || '未知'})</summary><div class="player-basic-info"><div class="lingneng"><strong>灵能总量:</strong> <span>${playerBasic['灵能总量'] || '0'}</span></div><div><strong>精力:</strong> ${playerBasic['精力'] || '未知'}</div></div><div class="player-detailed-info"><div><i class="fas fa-male"></i><strong>肉棒状态:</strong> ${playerDetailed['肉棒状态'] || '未知'}</div><div><i class="fas fa-female"></i><strong>阴道状态:</strong> ${playerDetailed['阴道状态'] || '无'}</div><div><i class="fas fa-box"></i><strong>后庭状态:</strong> ${playerDetailed['后庭状态'] || '未开发'}</div></div></details><details open><summary><i class="fas fa-route"></i> 情欲道途</summary><div class="daopath-details-grid">`;
  const pathOrder = ['束缚', '支配', '魅惑', '改造', '暴露'];
  pathOrder.forEach(name => {
   const path = daoPaths.find(p => p[name] !== undefined);
   let proficiency = '未入门(0)'; let training = '0';
   if (path) { proficiency = path[name] || proficiency; training = path['锤炼'] !== undefined ? path['锤炼'] : training; }
   const desc = daoDescriptions[name] || '暂无描述。';
   let className = `dao-${name.toLowerCase()}`;
    if (name === '束缚') className = 'dao-shufu'; else if (name === '支配') className = 'dao-zhipei'; else if (name === '魅惑') className = 'dao-meihuo'; else if (name === '改造') className = 'dao-gaizao'; else if (name === '暴露') className = 'dao-baolu';
   html += `<div class="daopath-item"><div class="daopath-info ${className}"><strong>${name}:</strong><span>${proficiency} (锤炼: ${training})</span></div><p class="dao-description">${desc}</p></div>`;
  });
  html += `</div></details>`; panel.innerHTML = html;
 }

 </script>
</body>
